26	
27	std::shared_ptr<TransportManager> TransportManager::Create(TransportType type)
28	{
29	    switch (type) {
30	        case TT_HCCP:
31	#if defined(ACLSHMEM_RDMA_V2_SUPPORT)
32	            return std::make_shared<device::RdmaTransportManagerV2>();
33	#else
34	            return std::make_shared<device::RdmaTransportManager>();
35	#endif
36	        case TT_SDMA:
37	            return std::make_shared<device::SdmaTransportManager>();
38	#if defined(ACLSHMEM_SOC_950)
39	        case TT_UDMA:
40	            return std::make_shared<device::UdmaTransportManager>();
41	#endif
42	        default:
43	            SHM_LOG_ERROR("Invalid trans type: " << type);
44	            return nullptr;
45	    }
46	}
47	
48	std::shared_ptr<TransportManager> TransportManager::CreateForDataOpType(uint32_t dataOpType)
49	{
50	    std::vector<TransportType> order;
51	    if ((dataOpType & HYBM_DOP_TYPE_DEVICE_RDMA) != 0) {
52	        order.push_back(TT_HCCP);
53	    }
54	    if ((dataOpType & HYBM_DOP_TYPE_DEVICE_SDMA) != 0) {
55	        order.push_back(TT_SDMA);
56	    }
57	    if ((dataOpType & HYBM_DOP_TYPE_DEVICE_UDMA) != 0) {
58	        order.push_back(TT_UDMA);
59	    }
60	
61	    if (order.empty()) {
62	        return nullptr;
63	    }
64	    if (order.size() == 1) {
65	        return Create(order.front());
66	    }
67	    return std::make_shared<CompositeTransportManager>(std::move(order));
68	}
69	
70	const void* TransportManager::GetQpInfo() const
71	{
72	    SHM_LOG_DEBUG("Not Implement GetQpInfo()");
73	    return nullptr;
74	}
75	
76	TransportDeviceInfo TransportManager::GetDeviceInfo() const
77	{
78	    TransportDeviceInfo info;
79	    info.rdmaInfoAddress = reinterpret_cast<uint64_t>(GetQpInfo());
80	    return info;
81	}
82	
83	Result TransportManager::ConnectWithOptions(const HybmTransPrepareOptions& options)
84	{
85	    SHM_LOG_DEBUG("ConnectWithOptions now connected=" << connected_);
86	    if (!connected_) {
87	        auto ret = Prepare(options);
88	        if (ret != ACLSHMEM_SUCCESS) {
89	            SHM_LOG_ERROR("prepare connection failed: " << ret);
90	            return ret;
91	        }
92	
93	        ret = Connect();
94	        if (ret != ACLSHMEM_SUCCESS) {
95	            SHM_LOG_ERROR("connect failed: " << ret);
96	            return ret;
97	        }
98	
99	        connected_ = true;
100	        return ACLSHMEM_SUCCESS;
101	    }
102	
103	    return UpdateRankOptions(options);
104	}
